contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint d1, uint d2) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (d1) + (d2)); require(d1 <= 1000000000000000000000000000000); require(d2 <= 1000000000000000000000000000000);
        require(d1 > 0 && d2 > 0, "need positive deposits");
        require(address(this).balance >= d1 + d2, "insufficient test balance");

        c.deposit{value: d1}(); if (__ESBMC_reverted()) return;
        c.deposit{value: d2}(); if (__ESBMC_reverted()) return;

        uint totalDeposited = d1 + d2;
        uint beforeBalance = address(this).balance;
        uint beforeContractBalance = address(c).balance;

        c.withdrawAll(); if (__ESBMC_reverted()) return;

        uint afterBalance = address(this).balance;
        uint afterContractBalance = address(c).balance;

        assert(
            afterBalance == beforeBalance + totalDeposited &&
            afterContractBalance + totalDeposited == beforeContractBalance
        );
    }
    receive() external payable {}
}

