// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 d1, uint256 d2) internal {
        d1 = bound(d1, 0, 1000000000000000000000000000000);
        d2 = bound(d2, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(d1 > 0 && d2 > 0);
        vm.assume(address(this).balance >= d1 + d2);
        try c.deposit{value: d1}() {} catch { return; }
        try c.deposit{value: d2}() {} catch { return; }
        uint totalDeposited = d1 + d2;
        uint beforeBalance = address(this).balance;
        uint beforeContractBalance = address(c).balance;
        try c.withdrawAll() {} catch { return; }
        uint afterBalance = address(this).balance;
        uint afterContractBalance = address(c).balance;
        assertTrue(afterBalance == beforeBalance + totalDeposited &&
            afterContractBalance + totalDeposited == beforeContractBalance);
    }

    function testFuzz_run(uint256 d1, uint256 d2) public {
        _run(d1, d2);
    }

    receive() external payable {}
}
